 RETURNS TABLE(site_id uuid, path text, page_id uuid, page_version_id uuid, render_manifest jsonb, shell_revision bigint, shell_payload jsonb, is_staging boolean, canonical_host text, redirect_to text, updated_at timestamp with time zone)
